// Bytes of assets/logo-oficial-motolinkpro-nobg.png (embedded for reliable display on web).
// Regenerate: python3 tool/embed_logo.py
import 'dart:convert';
import 'dart:typed_data';

Uint8List decodeMotoLinkProLogoPng() {
  return Uint8List.fromList(base64Decode(_kLogoB64));
}

const String _kLogoB64 = '';
